/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
for p in sorted(Path('fragments').glob('*.json')):
 data=json.loads(p.read_text())
 for d in data:
  if d['number'] in ('L145-5-2','L146-2'):
   d['proposed_xml']=d['proposed_xml'].replace('pour des faits commis dans les cinq ans suivant sa notification','pour des faits commis dans un délai de cinq ans à compter de sa notification')
  if d['number']=='L145-5-6':
   d['review_notes']=\"Le renvoi au premier alinéa reste à sa place. Majorité, égalité des effectifs et libre choix en cas d'égalité sont conservés. Les renvois à L. 145-2 et L. 145-4 sont maintenus. Vérification en lecture seule dans le corpus : L. 145-2 énumère des sanctions, tandis que L. 145-4 habilite un décret en Conseil d'État à étendre et adapter le chapitre aux pharmaciens et à certains auxiliaires médicaux et à fixer ses modalités d'application et de procédure ; il n'énumère pas lui-même de sanctions. Cette difficulté préexistante du renvoi appelle un contrôle de coordination avec les dispositions réglementaires, sans substitution inventée. La limite d'un an reste réservée à l'interdiction temporaire d'activités de biologie médicale.\"
  if d['number']=='L145-7-1':
   d['proposed_xml']=d['proposed_xml'].replace('Les frais de déplacement de ces présidents sont remboursés selon la réglementation applicable aux fonctionnaires de l’État.','Leurs frais de déplacement sont remboursés selon la réglementation applicable aux fonctionnaires de l’État.')
   d['proposed_xml']=d['proposed_xml'].replace(\"Les frais de déplacement de ces présidents sont remboursés selon la réglementation applicable aux fonctionnaires de l'État.\",\"Leurs frais de déplacement sont remboursés selon la réglementation applicable aux fonctionnaires de l'État.\")
  if d['number']=='L145-9-2':
   d['proposed_xml']=d['proposed_xml'].replace(\"peuvent statuer par ordonnance. Ils peuvent donner acte d'un désistement\", \"peuvent, par ordonnance, donner acte d'un désistement\")
   d['proposed_xml']=d['proposed_xml'].replace('Ils peuvent également statuer sur les requêtes','Ils peuvent également statuer par ordonnance sur les requêtes')
  if d['number']=='L146-2':
   d['proposed_xml']=d['proposed_xml'].replace(\"lorsque, dans le délai fixé à l'alinéa précédent, le praticien sanctionné n'a commis aucune nouvelle faute suivie d'une sanction.\",\"lorsque le praticien sanctionné n'a commis aucune nouvelle faute suivie d'une sanction dans le délai fixé à l'alinéa précédent.\")
 p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\\n')
s=json.loads(Path('source.json').read_text())
f=[]
for p in sorted(Path('fragments').glob('*.json')): f.extend(json.loads(p.read_text()))
by={d['number']:d for d in f}
a=[]
for src in s:
 d=by[src['number']]
 a.append({**{k:src[k] for k in ('code_id','source_id','source_sha256','number')},**{k:d[k] for k in ('proposed_xml','reason','review_notes')},'status':'rewrite_draft'})
Path('answer.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\\n')
for d in a:
 if d['number'] in ('L145-5-2','L145-5-6','L145-7-1','L145-9-2','L146-2'):
  print('\\n',d['number'],'\\n',d['proposed_xml'],'\\n',d['review_notes'])
PY"

